func ZoneProtectionProfileDataSourceSchema() dsschema.Schema {
	return dsschema.Schema{
		Attributes: map[string]dsschema.Attribute{

			"location": ZoneProtectionProfileDataSourceLocationSchema(),

			"name": dsschema.StringAttribute{
				Description: "",
				Required:    true,
			},

			"asymmetric_path": dsschema.StringAttribute{
				Description: "actions for TCP sliding window tracking errors, also control enable/disable TCP sequence number check for FIN/RST",
				Optional:    true,
				Computed:    true,
			},

			"description": dsschema.StringAttribute{
				Description: "",
				Optional:    true,
				Computed:    true,
			},

			"discard_icmp_error": dsschema.BoolAttribute{
				Description: "Discard ICMP embedded with error message",
				Optional:    true,
				Computed:    true,
			},

			"discard_icmp_frag": dsschema.BoolAttribute{
				Description: "Discard ICMP fragment",
				Optional:    true,
				Computed:    true,
			},

			"discard_icmp_large_packet": dsschema.BoolAttribute{
				Description: "Discard Large ICMP packet (IP length > 1024B)",
				Optional:    true,
				Computed:    true,
			},

			"discard_icmp_ping_zero_id": dsschema.BoolAttribute{
				Description: "Discard ICMP Ping with zero ID",
				Optional:    true,
				Computed:    true,
			},

			"discard_ip_frag": dsschema.BoolAttribute{
				Description: "Discard IP fragment",
				Optional:    true,
				Computed:    true,
			},

			"discard_ip_spoof": dsschema.BoolAttribute{
				Description: "Discard spoofed IP packet",
				Optional:    true,
				Computed:    true,
			},

			"discard_loose_source_routing": dsschema.BoolAttribute{
				Description: "Discard packets with loose source routing IP option",
				Optional:    true,
				Computed:    true,
			},

			"discard_malformed_option": dsschema.BoolAttribute{
				Description: "Discard packets with malformed IP option",
				Optional:    true,
				Computed:    true,
			},

			"discard_overlapping_tcp_segment_mismatch": dsschema.BoolAttribute{
				Description: "Discard sessions with mismatch tcp overlapping segment",
				Optional:    true,
				Computed:    true,
			},

			"discard_record_route": dsschema.BoolAttribute{
				Description: "Discard packets with Record Route IP option",
				Optional:    true,
				Computed:    true,
			},

			"discard_security": dsschema.BoolAttribute{
				Description: "Discard packets with Security IP option",
				Optional:    true,
				Computed:    true,
			},

			"discard_stream_id": dsschema.BoolAttribute{
				Description: "Discard packets with Stream ID IP option",
				Optional:    true,
				Computed:    true,
			},

			"discard_strict_source_routing": dsschema.BoolAttribute{
				Description: "Discard packets with strict source routing IP option",
				Optional:    true,
				Computed:    true,
			},

			"discard_tcp_split_handshake": dsschema.BoolAttribute{
				Description: "Discard tcp split handshake packet",
				Optional:    true,
				Computed:    true,
			},

			"discard_tcp_syn_with_data": dsschema.BoolAttribute{
				Description: "Discard tcp syn packet with data payload",
				Optional:    true,
				Computed:    true,
			},

			"discard_tcp_synack_with_data": dsschema.BoolAttribute{
				Description: "Discard tcp syn ack packet with data payload",
				Optional:    true,
				Computed:    true,
			},

			"discard_timestamp": dsschema.BoolAttribute{
				Description: "Discard packets with Timestmp IP option",
				Optional:    true,
				Computed:    true,
			},

			"discard_unknown_option": dsschema.BoolAttribute{
				Description: "Discard packets with unknown IP option",
				Optional:    true,
				Computed:    true,
			},

			"flood": ZoneProtectionProfileDataSourceFloodSchema(),

			"ipv6": ZoneProtectionProfileDataSourceIpv6Schema(),

			"l2_sec_group_tag_protection": ZoneProtectionProfileDataSourceL2SecGroupTagProtectionSchema(),

			"net_inspection": ZoneProtectionProfileDataSourceNetInspectionSchema(),

			"non_ip_protocol": ZoneProtectionProfileDataSourceNonIpProtocolSchema(),

			"remove_tcp_timestamp": dsschema.BoolAttribute{
				Description: "Remove TCP Timestamp",
				Optional:    true,
				Computed:    true,
			},

			"scan": dsschema.ListNestedAttribute{
				Description:  "",
				Optional:     true,
				Computed:     true,
				NestedObject: ZoneProtectionProfileDataSourceScanSchema(),
			},

			"scan_white_list": dsschema.ListNestedAttribute{
				Description:  "",
				Optional:     true,
				Computed:     true,
				NestedObject: ZoneProtectionProfileDataSourceScanWhiteListSchema(),
			},

			"strict_ip_check": dsschema.BoolAttribute{
				Description: "Perform strict IP address check",
				Optional:    true,
				Computed:    true,
			},

			"strip_mptcp_option": dsschema.StringAttribute{
				Description: "strip mptcp option",
				Optional:    true,
				Computed:    true,
			},

			"strip_tcp_fast_open_and_data": dsschema.BoolAttribute{
				Description: "Strip tcp fast option and data payload",
				Optional:    true,
				Computed:    true,
			},

			"suppress_icmp_needfrag": dsschema.BoolAttribute{
				Description: "Do not reply ICMP NEEDFRAG (layer3 only)",
				Optional:    true,
				Computed:    true,
			},

			"suppress_icmp_timeexceeded": dsschema.BoolAttribute{
				Description: "Do not reply ICMP TTL expired error (layer3 only)",
				Optional:    true,
				Computed:    true,
			},

			"tcp_reject_non_syn": dsschema.StringAttribute{
				Description: "reject non-SYN TCP packet for session setup",
				Optional:    true,
				Computed:    true,
			},
		},
	}
}

